<script setup>
import { computed, ref, onMounted } from 'vue'
import { useLearning, percent } from '../store'
import MathText from '../components/MathText.vue'
const store=useLearning(), data=ref(null), sortBy=ref('')
async function load(){ if(store.isStaff) await store.run(async()=>{ data.value=await store.api('/teacher/dashboard') }) }
// Cell colour follows the same pass/review/learning states the students see; untouched cells stay blank.
const tone=c=>!c.samples?'':c.status==='已通过'?'pass':c.status==='建议复习'?'review':c.mastery<data.value.low_mastery_threshold?'low':'learning'
const students=computed(()=>{ const rows=[...(data.value?.students||[])]; if(sortBy.value) rows.sort((a,b)=>(a.cells[sortBy.value]?.mastery??2)-(b.cells[sortBy.value]?.mastery??2)); return rows })
const totals=computed(()=>{ const s=data.value?.students||[]; return {students:s.length, active:s.filter(x=>x.attempts).length, attempts:s.reduce((t,x)=>t+x.attempts,0), stuck:(data.value?.sticking_points||[]).reduce((t,x)=>t+x.count,0)} })
onMounted(load)
</script>
<template><div v-if="!store.isStaff" class="empty">需要本课程老师或助教权限</div><template v-else><div class="page-heading"><div><p class="eyebrow">{{ store.currentCourse?.name }} · 教学看板</p><h1>看清全班卡在哪里</h1><p>所有数据由答题记录和现有规则实时计算，不调用模型；掌握度是启发式估计。</p></div><button class="secondary" @click="load">刷新</button></div>
<template v-if="data"><div v-if="data.simulated_students" class="callout">其中 {{ data.simulated_students }} 名学生含模拟历史（演示账号），请勿当作真实班级数据解读。</div>
<div class="metrics"><div><span>选课学生</span><strong data-testid="teacher-students">{{ totals.students }}</strong></div><div><span>有作答记录</span><strong>{{ totals.active }}</strong></div><div><span>累计作答</span><strong>{{ totals.attempts }}</strong></div><div><span>有明确下一步的学生</span><strong>{{ totals.stuck }}</strong></div></div>
<section class="panel"><div class="section-heading"><div><h2>共同卡点</h2><p>按推荐算法给出的“下一步”分组：同一组学生应先补同一个知识点，“影响”列出它挡住的后续内容。</p></div></div><div v-if="data.sticking_points.length" class="stuck-list"><article v-for="p in data.sticking_points" :key="p.knowledge_id" data-testid="sticking-point"><strong>{{ p.count }} 人卡在「{{ p.name }}」</strong><p>{{ p.students.join('、') }}</p><small v-if="p.blocks.length">影响：{{ p.blocks.join('、') }}</small></article></div><p v-else class="muted">暂无作答记录，无法判断卡点。</p></section>
<section class="panel table-scroll"><div class="section-heading"><div><h2>掌握度矩阵</h2><p>点击知识点列名，按该知识点掌握度从低到高排序；空白表示尚未作答。</p></div><div class="legend"><span class="cell pass">已通过</span><span class="cell learning">学习中</span><span class="cell low">低于 {{ percent(data.low_mastery_threshold) }}</span><span class="cell review">建议复习</span></div></div><table class="matrix"><thead><tr><th>学生</th><th>作答</th><th v-for="k in data.knowledge" :key="k.id"><button class="text-button" :class="{active:sortBy===k.id}" @click="sortBy=sortBy===k.id?'':k.id" :title="k.chapter">{{ k.name }}</button></th></tr></thead><tbody><tr v-for="s in students" :key="s.user_id"><th>{{ s.username }}<span v-if="s.is_demo" class="badge">演示</span></th><td>{{ s.attempts }}</td><td v-for="k in data.knowledge" :key="k.id"><span class="cell" :class="tone(s.cells[k.id])" :title="`${s.cells[k.id].status} · ${s.cells[k.id].samples} 条样本`">{{ s.cells[k.id].samples ? percent(s.cells[k.id].mastery) : '' }}</span></td></tr></tbody></table><p v-if="!data.students.length" class="muted">本课程还没有学生。</p></section>
<div class="teacher-grid"><section class="panel table-scroll"><h2>知识点概况</h2><table><thead><tr><th>知识点</th><th>已评估</th><th>已通过</th><th>偏低</th><th>平均掌握度</th><th>近 7 天作答</th></tr></thead><tbody><tr v-for="n in data.summary" :key="n.knowledge_id"><td>{{ n.name }}</td><td>{{ n.assessed }}</td><td>{{ n.passed }}</td><td>{{ n.low }}</td><td>{{ percent(n.average_mastery) }}</td><td>{{ n.attempts_7d }}</td></tr></tbody></table></section>
<section class="panel"><h2>高频错题</h2><div v-for="m in data.frequent_mistakes" :key="m.question_id" class="frequent-mistake"><strong>#{{ m.question_id }} · {{ m.knowledge }}</strong><p><MathText :text="m.stem"/></p><small>{{ m.errors }} 次错误 · {{ m.students }} 名学生</small></div><p v-if="!data.frequent_mistakes.length" class="muted">暂无错题。</p></section></div></template></template></template>

<style scoped>
.stuck-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:14px}.stuck-list article{border:1px solid var(--border);border-left:3px solid var(--purple);border-radius:8px;padding:14px 16px}.stuck-list p{font-size:12px;margin:6px 0}.stuck-list small{font-size:11px;color:var(--muted)}
.matrix th,.matrix td{padding:6px 8px;border-bottom:1px solid var(--border);white-space:nowrap}.matrix thead th{font-weight:500}.matrix tbody th{font-weight:500}.matrix .text-button{font-size:11px;padding:0}.matrix .text-button.active{font-weight:700;text-decoration:underline}.matrix .badge{margin-left:6px;font-size:9px;padding:1px 5px}
.cell{display:inline-block;min-width:42px;padding:3px 6px;border-radius:4px;font-size:11px;text-align:center}.cell.pass{background:#e1f5ee;color:#0f6e56}.cell.learning{background:#eeedfe;color:#534ab7}.cell.low{background:#fde8e8;color:#a33a3a}.cell.review{background:#faeeda;color:#854f0b}
.legend{display:flex;gap:6px;flex-wrap:wrap}.teacher-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:20px;align-items:start}.teacher-grid td,.teacher-grid th{padding:7px 8px;border-bottom:1px solid var(--border);white-space:nowrap}.frequent-mistake{border-bottom:1px solid var(--border);padding:10px 0}.frequent-mistake p{font-size:12px;margin:4px 0}.frequent-mistake small{font-size:11px;color:var(--muted)}
@media(max-width:1100px){.teacher-grid{grid-template-columns:1fr}}
</style>
